export const DEMOS = [...SCENARIOS.map(sc => ({ ...sc, ...META[sc.id] })), ...NEW].filter(d => ORDER.includes(d.id)).sort((a, b) => ORDER.indexOf(a.id) - ORDER.indexOf(b.id)).map(d => ({ ...d, title: TITLE[d.id] || d.title, who: MODE_OVR[d.id] || MODE[d.who] || d.who }));
